import{_ as s,o as n,a as e,b as t}from"./app.UgfkfLuP.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"数据重排","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/data_reorder"},{"text":"expand","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/expand"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/expand.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/expand.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793005388000}'),p={name:"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/expand.md"};function l(c,a,o,r,d,i){return n(),e("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>expand</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_compute_sel.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p>根据掩码生成排除当前位置的前缀计数索引：结果第0个元素为0，第i个元素等于<code>mask.reg</code>中第0至第i-1个元素对应的有效比特中1的数量。按T的元素位宽解释掩码，最后一个元素对应的掩码位不参与任何结果元素的计数。</p><p>例如，掩码前六个元素对应的有效比特为<code>{1, 0, 1, 1, 0, 1}</code>时，结果前六个元素为<code>{0, 1, 1, 2, 3, 3}</code>。</p><p>本接口生成索引，不接收待展开的数据，也不直接将压缩数据恢复到原位置。本接口仅在AIV上生效。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">expand</span><span class="p">(</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">bool</span><span class="o">&gt;</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>结果索引的元素类型，须显式指定。支持的类型请参见<a href="#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 函数参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mask</td><td>输入</td><td>源掩码，类型为<a href="../reg_tensor/reg_tensor.html">reg_tensor&lt;bool&gt;</a>。<code>mask.reg</code>参与前缀计数，并作为返回对象的掩码。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>T支持：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回<code>reg_tensor&lt;T&gt;</code>，<code>reg</code>保存前缀计数索引，<code>mask</code>等于输入对象的<code>mask.reg</code>，不是输入对象的<code>mask.mask</code>。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><code>mask.reg</code>须已初始化，且须按T的元素位宽构造。<code>mask.mask</code>不参与计算。</li><li>结果数据寄存器包含逐元素前缀计数，但返回对象的掩码只选中输入掩码为1的位置。如果需要在后续操作中使用全部前缀计数，须重新绑定全有效掩码。</li><li>有符号结果类型仍受对应类型可表示范围限制。例如，int8_t不能表示大于127的非负计数，需要保留该范围以上计数时应选用适合的数据类型。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下代码片段在VF中调用。<code>selection.reg</code>已初始化，按uint16_t的元素位宽构造。默认返回对象的掩码等于<code>selection.reg</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">expand_example</span><span class="p">(</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">bool</span><span class="o">&gt;</span><span class="w"> </span><span class="n">selection</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">expand</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">selection</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const v=s(p,[["render",l]]);export{_ as __pageData,v as default};
